12	func (d *DB) CreateIdentityProvider(ctx context.Context, create *store.IdentityProvider) (*store.IdentityProvider, error) {
13		placeholders := []string{"?", "?", "?", "?", "?"}
14		fields := []string{"`uid`", "`name`", "`type`", "`identifier_filter`", "`config`"}
15		args := []any{create.UID, create.Name, create.Type.String(), create.IdentifierFilter, create.Config}
16	
17		stmt := "INSERT INTO `idp` (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholders, ", ") + ") RETURNING `id`"
18		if err := d.db.QueryRowContext(ctx, stmt, args...).Scan(&create.ID); err != nil {
19			return nil, err
20		}
21	
22		identityProvider := create
23		return identityProvider, nil
24	}
